<script setup>
import { ref, computed } from 'vue';
import { Head, router } from '@inertiajs/vue3';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import axios from 'axios';
const props = defineProps({ employees:Array, year:Number, month:Number, page:Number, pages:Number, total:Number, search:String });
const rows=ref(props.employees.map(e=>({...e, selected:false, dirty:false, reason:'', evidence_reference:'', additions:(e.additions||[]).map(c=>({...c})), deductions:(e.deductions||[]).map(c=>({...c})), arrears:(e.arrears||[]).map(c=>({...c}))})));
const selected=computed(()=>rows.value.filter(x=>x.selected && !x.posted && !x.error));
const busy=ref(false), results=ref([]), search=ref(props.search||''), status=ref('draft');
function mark(e){e.dirty=true; e.selected=true;}
function navigate(page=1){router.get('/dashboard/salary/estimation/bulk-salary-review',{year:2026,month:10,page,search:search.value},{preserveState:false});}
function rowNet(e){const value=c=>Number(c.amount||0);const regAdds=e.additions.reduce((a,c)=>a+(c.calcType==='percentage'?0:value(c)),0);const regDeds=e.deductions.reduce((a,c)=>a+(c.calcType==='percentage'?0:value(c)),0);const ap=e.arrears.filter(a=>a.direction==='payable').reduce((s,a)=>s+Number(a.final_amount||0),0);const ad=e.arrears.filter(a=>a.direction==='deduction').reduce((s,a)=>s+Number(a.final_amount||0),0);return {estimate:regAdds-regDeds+ap-ad,percentagePresent:[...e.additions,...e.deductions].some(a=>a.calcType==='percentage'),missing:e.arrears.some(a=>a.final_amount===null||a.final_amount==='')};}
async function save(){if(busy.value||!selected.value.length)return;busy.value=true;results.value=[];
 try{const data={year:2026,month:10,items:selected.value.map(e=>({user_id:e.user_id,status:status.value,expected_version:e.version,additions:e.additions,deductions:e.deductions,arrear_rows:e.arrears,reason:e.reason,evidence_reference:e.evidence_reference}))};
 const res=await axios.post('/dashboard/salary/estimation/bulk-salary-review/save',data);
 results.value=res.data.results||[];
 for(const r of results.value){const e=rows.value.find(x=>x.user_id===r.user_id);if(r.ok&&e){e.version=r.version;e.status=r.status;e.selected=false;e.dirty=false;}}
 }catch(error){results.value=[{ok:false,message:error.response?.data?.message||'Request failed. No success assumed.'}];}finally{busy.value=false;}}
function addComponent(e,direction){const arr=direction==='addition'?e.additions:e.deductions; arr.push({name:'New component',calcType:'fixed',amount:0});mark(e);}
function addArrear(e,direction){e.arrears.push({rule_id:null,title:'Custom arrear',direction,mode:'fixed',code:null,calculated_amount:null,final_amount:0,months:[],reason:'',evidence_reference:''});mark(e);}
function selectPage(v){rows.value.forEach(e=>{if(!e.posted&&!e.error)e.selected=v;});}
</script>
<template>
<Head title="Bulk Salary Review"/>
<AuthenticatedLayout>
<div class="mx-auto max-w-[1720px] space-y-4 p-4 lg:p-7">
<header class="rounded-xl bg-white p-5 shadow-sm"><h1 class="text-xl font-bold">Bulk Salary Spreadsheet Editor — October 2026</h1><p class="text-sm text-slate-600">Same versioned Salary Calculator save endpoint. Draft keeps unresolved data for HR review; Approve uses existing financial checks. Neither posts a bill.</p></header>
<div class="flex flex-wrap items-center gap-2 rounded-lg bg-white p-4"><input v-model="search" @keyup.enter="navigate(1)" placeholder="Employee name / code" class="rounded border p-2 text-sm"/><button @click="navigate(1)" class="rounded bg-slate-800 px-3 py-2 text-white">Search</button><span class="ml-auto text-sm">{{total}} profiles · Page {{page}}/{{pages}} · {{selected.length}} selected</span><button @click="selectPage(true)" class="rounded border p-2">Select page</button><button @click="selectPage(false)" class="rounded border p-2">Clear</button></div>
<div class="sticky top-2 z-20 flex flex-wrap items-center gap-3 rounded-xl border border-indigo-200 bg-indigo-50 p-3 shadow"><label class="text-sm">Save as <select v-model="status" class="rounded border p-2"><option value="draft">Draft (review first)</option><option value="approved">Approved (financial checks apply)</option></select></label><button @click="save" :disabled="busy||!selected.length" class="rounded bg-emerald-700 px-5 py-2 font-semibold text-white disabled:opacity-40">{{busy?'Saving…':`Save ${selected.length} employees`}}</button><a href="/dashboard/salary/estimation" class="rounded border p-2 text-sm">Estimation list</a><span class="text-xs text-amber-900">Missing evidence is not treated as verified zero.</span></div>
<div v-if="results.length" class="max-h-40 overflow-y-auto rounded border bg-white p-3 text-xs"><p v-for="(r,i) in results" :key="i" :class="r.ok?'text-emerald-700':'text-rose-700'">{{r.user_id||'Request'}} — {{r.ok?`Saved v${r.version} (${r.status})`:r.message}}</p></div>
<section v-for="e in rows" :key="e.user_id" class="rounded-xl border bg-white p-4 shadow-sm">
<div class="flex flex-wrap items-center gap-3 border-b pb-3"><input v-model="e.selected" type="checkbox" :disabled="!!e.posted||!!e.error"/><div class="flex-1"><b>{{e.code}} — {{e.name}}</b><p class="text-xs text-slate-500">{{e.status}} · Version {{e.version}} · {{e.posted?'GENERATED — cannot modify':'Not posted'}}</p></div><span v-if="e.error" class="text-xs text-red-600">{{e.error}}</span><span v-else class="text-sm font-semibold">{{rowNet(e).missing?'Arrear incomplete':rowNet(e).percentagePresent?'Percentage rules: verify calculator':'Estimated net ৳'+rowNet(e).estimate.toFixed(2)}}</span><a :href="`/dashboard/salary/calculator/${e.user_id}?year=2026&month=10`" class="text-sm text-indigo-700 underline">Full Calculator</a></div>
<div v-if="!e.error" class="mt-3 grid gap-4 xl:grid-cols-3">
<div class="min-w-0"><h3 class="mb-2 font-semibold text-emerald-800">Allowances / Basic</h3><div v-for="(c,i) in e.additions" :key="i" class="mb-1 flex flex-wrap gap-1"><input v-model="c.name" @input="mark(e)" class="min-w-[120px] flex-1 rounded border p-1 text-xs"/><select v-model="c.calcType" @change="mark(e)" class="rounded border p-1 text-xs"><option value="fixed">৳</option><option value="percentage">%</option></select><input v-model.number="c.amount" @input="mark(e)" type="number" min="0" step="0.01" class="w-24 rounded border p-1 text-xs"/><button @click="e.additions.splice(i,1);mark(e)" class="text-rose-700">×</button></div><button @click="addComponent(e,'addition')" class="mt-1 rounded bg-emerald-50 px-2 py-1 text-xs">+ Allowance</button></div>
<div class="min-w-0"><h3 class="mb-2 font-semibold text-rose-800">Deductions / GPF</h3><div v-for="(c,i) in e.deductions" :key="i" class="mb-1 flex flex-wrap gap-1"><input v-model="c.name" @input="mark(e)" class="min-w-[120px] flex-1 rounded border p-1 text-xs"/><select v-model="c.calcType" @change="mark(e)" class="rounded border p-1 text-xs"><option value="fixed">৳</option><option value="percentage">%</option></select><input v-model.number="c.amount" @input="mark(e)" type="number" min="0" step="0.01" class="w-24 rounded border p-1 text-xs"/><button @click="e.deductions.splice(i,1);mark(e)" class="text-rose-700">×</button></div><button @click="addComponent(e,'deduction')" class="mt-1 rounded bg-rose-50 px-2 py-1 text-xs">+ Deduction</button><p class="mt-2 text-xs text-amber-700">Existing monthly GPF overrides remain authoritative; edit conflicts in Full Calculator.</p></div>
<div class="min-w-0"><h3 class="mb-2 font-semibold">Arrear payable / deductions</h3><div v-for="(a,i) in e.arrears" :key="i" class="mb-2 rounded border p-2"><div class="flex gap-1"><input v-model="a.title" @input="mark(e)" class="min-w-0 flex-1 rounded border p-1 text-xs"/><select v-model="a.direction" @change="mark(e)" class="rounded border p-1 text-xs"><option value="payable">+</option><option value="deduction">−</option></select><button v-if="!a.rule_id" @click="e.arrears.splice(i,1);mark(e)">×</button></div><div class="mt-1 flex gap-1"><input v-model.number="a.final_amount" @input="mark(e)" type="number" min="0" step="0.01" class="w-28 rounded border p-1 text-xs" placeholder="Amount"/><input v-model="a.reason" @input="mark(e)" placeholder="Reason" class="min-w-0 flex-1 rounded border p-1 text-xs"/><input v-model="a.evidence_reference" @input="mark(e)" placeholder="Evidence" class="min-w-0 flex-1 rounded border p-1 text-xs"/></div></div><div class="flex gap-2"><button @click="addArrear(e,'payable')" class="rounded bg-emerald-50 px-2 py-1 text-xs">+ Payable</button><button @click="addArrear(e,'deduction')" class="rounded bg-rose-50 px-2 py-1 text-xs">+ Recovery</button></div></div>
</div><div class="mt-3 grid gap-2 md:grid-cols-2"><input v-model="e.reason" @input="mark(e)" placeholder="HR revision reason" class="rounded border p-2 text-sm"/><input v-model="e.evidence_reference" @input="mark(e)" placeholder="HR evidence reference" class="rounded border p-2 text-sm"/></div></section>
<div class="flex items-center justify-between rounded-lg bg-white p-3"><button @click="navigate(Math.max(1,page-1))" :disabled="page<=1" class="rounded border p-2 disabled:opacity-40">Previous 20</button><span>Page {{page}} / {{pages}}</span><button @click="navigate(Math.min(pages,page+1))" :disabled="page>=pages" class="rounded border p-2 disabled:opacity-40">Next 20</button></div>
</div>
</AuthenticatedLayout>
</template>
